<script setup lang="ts">
import {ref,watch} from 'vue'
const props=defineProps<{modelValue:Record<string,any>}>()
const emit=defineEmits<{(e:'update:modelValue',value:Record<string,any>):void;(e:'validity',value:boolean):void}>()
type Row={id:string;path:string;type:string;value:string}
const rows=ref<Row[]>([]),error=ref('');let last=''
function kind(value:any){return value===null?'null':typeof value==='object'?'json':typeof value==='number'?'number':typeof value==='boolean'?'boolean':'text'}
watch(()=>props.modelValue,value=>{const json=JSON.stringify(value||{});if(json===last)return;last=json;rows.value=Object.entries(value||{}).map(([path,value])=>({id:crypto.randomUUID(),path,type:kind(value),value:typeof value==='object'?JSON.stringify(value):String(value)}));error.value='';emit('validity',true)},{immediate:true,deep:true})
function update(){try{const result:Record<string,any>={};for(const row of rows.value){const path=row.path.trim();if(!path)throw new Error('请填写字段路径');if(path in result)throw new Error('字段路径不能重复');let value:any=row.value;if(row.type==='number'){if(!value.trim()||!Number.isFinite(Number(value)))throw new Error('期望值需要是数字');value=Number(value)}else if(row.type==='boolean')value=value==='true';else if(row.type==='null')value=null;else if(row.type==='json')value=JSON.parse(value);result[path]=value}error.value='';last=JSON.stringify(result);emit('update:modelValue',result);emit('validity',true)}catch(e){error.value=e instanceof SyntaxError?'数组或对象需要有效的 JSON':(e as Error).message;emit('validity',false)}}
function add(){rows.value.push({id:crypto.randomUUID(),path:'',type:'text',value:''});update()}
function remove(index:number){rows.value.splice(index,1);update()}
</script>
<template><div class="json-assertions"><div class="step-section-heading"><strong>JSON 字段断言</strong><button class="text-button" type="button" @click="add">＋ 添加断言</button></div><div v-for="(row,index) in rows" :key="row.id" class="assertion-row"><label class="field-label">字段路径<input v-model="row.path" :aria-label="'断言字段 '+(index+1)" placeholder="$.data.token" @input="update"/></label><span class="assertion-equals">等于</span><label class="field-label">类型<select v-model="row.type" class="select" @change="row.value=row.type==='boolean'?'true':row.type==='json'?'{}':row.type==='number'?'0':'';update()"><option value="text">文本</option><option value="number">数字</option><option value="boolean">布尔值</option><option value="null">null</option><option value="json">数组／对象</option></select></label><label class="field-label">期望值<select v-if="row.type==='boolean'" v-model="row.value" class="select" @change="update"><option>true</option><option>false</option></select><input v-else v-model="row.value" :aria-label="'断言期望值 '+(index+1)" :disabled="row.type==='null'" @input="update"/></label><button class="icon-button danger" type="button" :aria-label="'删除断言 '+(index+1)" @click="remove(index)">×</button></div><p v-if="error" class="inline-error" role="alert">{{error}}</p><p v-if="!rows.length" class="form-hint">添加字段、比较关系和期望值。复杂比较可单独添加“检查响应”步骤。</p></div></template>
